#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    int v = *max_element(a.begin(), a.end());
    vector<long long> freq(v + 2, 0), prefix(v + 2, 0);
    for (int x : a) freq[x]++;
    for (int x = 1; x <= v; x++) prefix[x] = prefix[x - 1] + freq[x];
    // following[x]: first height above x whose count is at most 1
    vector<int> following(v + 2, v + 1);
    int last = v + 1;
    for (int x = v; x >= 1; x--) {
        following[x] = last;
        if (freq[x] <= 1) last = x;
    }
    long long best = 0;
    int lo = 1, hi = 1;
    for (int left = 1; left <= v; left++) {
        if (!freq[left]) continue;
        int stop = following[left];
        int right = stop <= v && freq[stop] == 1 ? stop : stop - 1;
        long long count = prefix[right] - prefix[left - 1];
        if (count > best) best = count, lo = left, hi = right;
    }
    // one of each height going up, then the remaining people coming down
    string out = to_string(best) + "\n";
    bool firstOut = true;
    auto put = [&](int x) {
        if (!firstOut) out += ' ';
        firstOut = false;
        out += to_string(x);
    };
    for (int x = lo; x <= hi; x++) put(x);
    for (int x = hi; x >= lo; x--)
        for (long long c = 1; c < freq[x]; c++) put(x);
    cout << out << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] a = new int[n];
        int v = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
            v = Math.max(v, a[i]);
        }
        long[] freq = new long[v + 2], prefix = new long[v + 2];
        for (int x : a) freq[x]++;
        for (int x = 1; x <= v; x++) prefix[x] = prefix[x - 1] + freq[x];
        // following[x]: first height above x whose count is at most 1
        int[] following = new int[v + 2];
        int last = v + 1;
        for (int x = v; x >= 1; x--) {
            following[x] = last;
            if (freq[x] <= 1) last = x;
        }
        long best = 0;
        int lo = 1, hi = 1;
        for (int left = 1; left <= v; left++) {
            if (freq[left] == 0) continue;
            int stop = following[left];
            int right = stop <= v && freq[stop] == 1 ? stop : stop - 1;
            long count = prefix[right] - prefix[left - 1];
            if (count > best) {
                best = count;
                lo = left;
                hi = right;
            }
        }
        // one of each height going up, then the remaining people coming down
        StringBuilder sb = new StringBuilder();
        sb.append(best).append('\n');
        boolean first = true;
        for (int x = lo; x <= hi; x++) {
            if (!first) sb.append(' ');
            first = false;
            sb.append(x);
        }
        for (int x = hi; x >= lo; x--)
            for (long c = 1; c < freq[x]; c++) sb.append(' ').append(x);
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	a := make([]int, n)
	v := 0
	for i := range a {
		a[i] = next()
		v = max(v, a[i])
	}
	freq, prefix := make([]int, v+2), make([]int, v+2)
	for _, x := range a {
		freq[x]++
	}
	for x := 1; x <= v; x++ {
		prefix[x] = prefix[x-1] + freq[x]
	}
	// following[x]: first height above x whose count is at most 1
	following := make([]int, v+2)
	last := v + 1
	for x := v; x >= 1; x-- {
		following[x] = last
		if freq[x] <= 1 {
			last = x
		}
	}
	best, lo, hi := 0, 1, 1
	for left := 1; left <= v; left++ {
		if freq[left] == 0 {
			continue
		}
		stop := following[left]
		right := stop - 1
		if stop <= v && freq[stop] == 1 {
			right = stop
		}
		if count := prefix[right] - prefix[left-1]; count > best {
			best, lo, hi = count, left, right
		}
	}
	// one of each height going up, then the remaining people coming down
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(best) + "\n")
	for x := lo; x <= hi; x++ {
		if x > lo {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(x))
	}
	for x := hi; x >= lo; x-- {
		for c := 1; c < freq[x]; c++ {
			w.WriteByte(' ')
			w.WriteString(strconv.Itoa(x))
		}
	}
	w.WriteByte('\n')
}
